contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
        require(_c.owner() == address(this));
    }

    function run(uint amount, uint withdrawAmount) public payable {
        require(address(this).balance >= amount);

        c.depositsCount();

        uint beforeBalance = address(c).balance;
        uint beforeTestBalance = address(this).balance;

        c.fallback{value: amount}();

        uint afterDepositBalance = address(c).balance;
        uint afterDepositCount = c.depositsCount();

        require(withdrawAmount <= address(c).balance);

        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            !reverted &&
            afterDepositBalance == beforeBalance + amount &&
            afterDepositCount == 2 &&
            address(c).balance == beforeBalance + amount - withdrawAmount &&
            address(this).balance == beforeTestBalance - amount + withdrawAmount
        );
    }

    receive() external payable {
        c.depositsCount();
    }
}

